#include <Wire.h>
#include <LiquidCrystal_I2C.h>
#include <Servo.h>

LiquidCrystal_I2C lcd(0x27, 16, 2);
Servo floodgateServo;
const int RAIN_PIN = A1;
const int WATER_PIN = A2;
const int FLOOD_LIMIT = 450;

void setup() {
  lcd.init(); lcd.backlight();
  floodgateServo.attach(9);
  floodgateServo.write(0); // Gate sealed
}

void loop() {
  int rainVal = analogRead(RAIN_PIN);
  int waterLevel = analogRead(WATER_PIN);

  lcd.setCursor(0, 0);
  lcd.print("Water: "); lcd.print(waterLevel);
  lcd.print(" Rain: "); lcd.print(rainVal < 600 ? "Y" : "N");

  if (waterLevel > FLOOD_LIMIT) {
    lcd.setCursor(0, 1);
    lcd.print("FLOODGATE OPEN! ");
    floodgateServo.write(90); // Open spillway
  } else {
    lcd.setCursor(0, 1);
    lcd.print("RESERVOIR SAFE  ");
    floodgateServo.write(0);  // Close spillway
  }
  delay(500);
}
